// ---- Image cache: 2 MB cap, least-recently-used entries evicted first ----

// Serializes store/trim work so concurrent image loads can't race.
var imageQueue = Promise.resolve();

function enqueue(task) {
  imageQueue = imageQueue.then(task).catch(function () {});
  return imageQueue;
}

async function trimImageCache(cache) {
  var entries = [];
  var total = 0;
  var requests = await cache.keys();

  for (var i = 0; i < requests.length; i++) {
    var response = await cache.match(requests[i]);
    if (!response) continue;

    var size = Number(response.headers.get("X-Img-Size")) || 0;
    var lastUsed = Number(response.headers.get("X-Img-Last-Used")) || 0;

    total += size;
    entries.push({ request: requests[i], size: size, lastUsed: lastUsed });
  }

  entries.sort(function (a, b) {
    return a.lastUsed - b.lastUsed;
  });

  while (total > IMAGE_MAX_BYTES && entries.length) {
    var victim = entries.shift();
    await cache.delete(victim.request);
    total -= victim.size;
  }
}

// Used both for the first download and to refresh "last used" on a hit.
async function storeImage(request, source, cache) {
  var body = await source.arrayBuffer();

  if (body.byteLength > IMAGE_MAX_BYTES) return;

  var headers = new Headers();
  headers.set("Content-Type", source.headers.get("Content-Type") || "application/octet-stream");
  headers.set("X-Img-Size", String(body.byteLength));
  headers.set("X-Img-Last-Used", String(Date.now()));

  await cache.put(request, new Response(body, { status: 200, headers: headers }));
  await trimImageCache(cache);
}

async function handleImage(event) {
  var request = event.request;
  var cache = await caches.open(IMAGE_CACHE);
  var cached = await cache.match(request);

  if (cached) {
    var forTouch = cached.clone(); // clone BEFORE the page consumes it
    event.waitUntil(enqueue(function () {
      return storeImage(request, forTouch, cache);
    }));
    return cached;
  }

  try {
    var response = await fetch(request);

    if (response.status === 200) {
      var forStore = response.clone(); // clone BEFORE returning
      event.waitUntil(enqueue(function () {
        return storeImage(request, forStore, cache);
      }));
    }

    return response;
  } catch (error) {
    // Offline and not cached: app.js shows the "image will be visible
    // when back online" note when the <img> fails.
    return new Response("", { status: 504, statusText: "Offline" });
  }
}

// ---- Routing ----

self.addEventListener("fetch", function (event) {
  var request = event.request;

  if (request.method !== "GET") return;

  var url = new URL(request.url);

  // Remote resources: browser default.
  if (url.origin !== self.location.origin) return;

  var key = url.origin + url.pathname; // ignores ?query and #hash

  if (url.href.indexOf(IMGCATCH_PREFIX) === 0) {
    event.respondWith(handleImage(event));
    return;
  }

  if (PRECACHE_HREFS.has(key)) {
    event.respondWith(
      caches.open(CORE_CACHE).then(function (cache) {
        return cache.match(key).then(function (cached) {
          return cached || fetch(request);
        });
      })
    );
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(
      caches.open(CORE_CACHE).then(function (cache) {
        return cache.match(INDEX_HREF).then(function (cached) {
          return cached || fetch(request);
        });
      })
    );
  }
});
